"""Deterministic generated files: ``index.md`` (catalog) and the Phase 1 ``core.md`` (L0 card).

No LLM involved. Output depends only on the wiki pages, the life map and the date (for "valid
today"), and contains no timestamps, so it is byte-stable while those don't change and the
local model's cached prompt prefix survives. Phase 4 consolidation replaces the core builder.
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from datetime import date
from pathlib import Path

from brain.index.temporal import valid_at
from brain.tokens import estimate_tokens
from brain.vault import gitops
from brain.vault.models import SELF_ID, WIKILINK, Fact, Page, link_target
from brain.vault.store import SELF_PAGE, Vault

GENERATED_NOTE = "<!-- generated by brain from wiki/ pages; manual edits are overwritten -->"
LINE_CHARS = 160

TYPE_GROUPS = {
    "self": "Self",
    "person": "People",
    "org": "Organisations",
    "project": "Projects",
    "place": "Places",
    "topic": "Topics",
    "event": "Events",
}

# Salience prior per predicate for the core card: what a friend would keep in mind first.
PREDICATE_WEIGHT: dict[str, float] = {
    "role": 10,
    "works_at": 9.5,
    "lives_in": 9,
    "team": 8,
    "manager": 7.5,
    "goal": 7.5,
    "partner_of": 7.5,
    "family_of": 7,
    "values": 7,
    "responsibility": 6.5,
    "friend_of": 6.5,
    "worked_on": 6,
    "health": 6,
    "has_strength": 5.5,
    "has_flaw": 5.5,
    "fears": 5.5,
    "interest": 5,
    "habit": 5,
    "speaks": 4.5,
    "hometown": 4.5,
    "nationality": 4.5,
    "born": 4,
    "likes": 4,
    "dislikes": 4,
    "has_skill": 4,
    "colleague_of": 4,
    "mentor_of": 4,
    "member_of": 4,
    "studied_at": 3.5,
    "degree": 3.5,
    "certification": 3,
    "knows": 2.5,
}
DEFAULT_WEIGHT = 2.0
KIND_BONUS = {"stated": 0.5, "observed": 0.0, "inferred": -1.5}
SECTION_SITUATION = "Current situation"
SECTION_ENTITIES = "People and projects"


# --- helpers -----------------------------------------------------------------------------------


def plain(text: str, titles: dict[str, str]) -> str:
    """Wikilinks as readable names: ``[[x|Sam]]`` → Sam, ``[[orgs/x]]`` → its page title."""

    def repl(m: re.Match[str]) -> str:
        raw = m.group(0)
        if "|" in raw:
            return raw[raw.index("|") + 1 : -2].strip()
        target = m.group(1).strip()
        return titles.get(target, target)

    return WIKILINK.sub(repl, text)


def first_sentence(text: str, limit: int = LINE_CHARS) -> str:
    flat = " ".join(text.split())
    m = re.search(r"(?<=[.!?])\s+(?=[A-Z0-9\[])", flat)
    sentence = flat[: m.start()] if m else flat
    if len(sentence) > limit:
        sentence = sentence[: limit - 1].rsplit(" ", 1)[0] + "…"
    return sentence


def validity_suffix(fact: Fact) -> str:
    """Same wording as the index items, so chat can skip memory hits already in the card."""
    if fact.valid_from and fact.valid_to:
        return f" ({fact.valid_from} to {fact.valid_to})"
    if fact.valid_from:
        return f" (since {fact.valid_from})"
    if fact.valid_to:
        return f" (until {fact.valid_to})"
    return ""


def _titles(pages: list[Page]) -> dict[str, str]:
    titles = {p.id: p.title for p in pages}
    titles[SELF_ID] = titles.get(SELF_PAGE, "the owner")
    return titles


def _visible(pages: list[Page], include_private: bool) -> list[Page]:
    return [p for p in pages if include_private or p.privacy != "private"]


# --- index.md ----------------------------------------------------------------------------------


def build_index(vault: Vault, *, include_private: bool = True) -> str:
    """``- [[id]] — summary`` per wiki page, grouped by the page's first life-map region."""
    pages = _visible(vault.pages(), include_private)
    titles = _titles(pages)
    lifemap = vault.lifemap
    order = list(lifemap.regions)
    groups: dict[str, list[str]] = {}
    for page in sorted(pages, key=lambda p: p.id):
        heading = None
        for region_id in page.regions:
            if region := lifemap.region(region_id):
                heading = region.label or region.id
                break
        heading = heading or TYPE_GROUPS.get(page.type, "Other")
        summary = first_sentence(plain(page.summary, titles)) if page.summary.strip() else ""
        groups.setdefault(heading, []).append(f"- [[{page.id}]] — {summary or page.title}")

    labels = [lifemap.regions[r].label or r for r in order]
    known = [h for h in labels if h in groups]
    rest = sorted(h for h in groups if h not in labels)
    out = ["# Index", "", GENERATED_NOTE]
    for heading in dict.fromkeys(known + rest):
        out += ["", f"## {heading}", "", *groups[heading]]
    return "\n".join(out) + "\n"


# --- core.md -----------------------------------------------------------------------------------


@dataclass(frozen=True)
class _Line:
    section: str
    text: str
    score: float
    key: tuple[str, ...]  # deterministic tie-break


def _fact_score(fact: Fact) -> float:
    return PREDICATE_WEIGHT.get(fact.p, DEFAULT_WEIGHT) + KIND_BONUS.get(fact.kind, 0.0)


def _is_self(value: str) -> bool:
    target = link_target(value)
    return target in (SELF_ID, SELF_PAGE)


def _owner_name(self_facts: list[Fact], profile: Page | None) -> str:
    names = sorted((f for f in self_facts if f.p == "name"), key=lambda f: f.id)
    if names:
        return link_target(names[0].o) or names[0].o
    if profile and profile.title.strip() and profile.title != "Profile":
        return profile.title
    return "The owner"


def build_core(
    vault: Vault,
    *,
    max_tokens: int = 1500,
    today: date | None = None,
    include_private: bool = True,
) -> str:
    """The L0 card: who the owner is, their current situation, and key people and projects.

    Facts must be current and valid today. Lines are ranked by a salience prior (predicate
    weight + stated/observed/inferred bonus, newest first on ties) and the card is filled
    greedily up to ``max_tokens``.
    """
    today = today or date.today()
    pages = _visible(vault.pages(), include_private)
    titles = _titles(pages)
    by_id = {p.id: p for p in pages}

    def current(fact: Fact) -> bool:
        try:
            return valid_at(fact.valid_from, fact.valid_to, today)
        except ValueError:
            return True

    self_pages = [p for p in pages if p.subject == SELF_ID]
    self_facts = [f for p in self_pages for f in p.facts if current(f)]
    profile = by_id.get(SELF_PAGE)
    name = _owner_name(self_facts, profile)

    lines: list[_Line] = []
    for fact in self_facts:
        if fact.p == "name":
            continue
        text = plain(fact.text, titles) + validity_suffix(fact)
        key = (f"{9999 - int((fact.valid_from or '0')[:4]):04d}", fact.p, text, fact.id)
        lines.append(_Line(SECTION_SITUATION, text, _fact_score(fact), key))

    # Entities tied to the owner by a current fact, in either direction.
    links: dict[str, float] = {}
    for fact in self_facts:
        target = link_target(fact.o)
        if target and target in by_id and by_id[target].subject != SELF_ID:
            links[target] = max(links.get(target, 0.0), _fact_score(fact)) + 0.1
    for page in pages:
        if page.subject == SELF_ID:
            continue
        for fact in page.facts:
            if current(fact) and _is_self(fact.o):
                links[page.id] = max(links.get(page.id, 0.0), _fact_score(fact)) + 0.1
    for page_id, score in links.items():
        page = by_id[page_id]
        about = first_sentence(plain(page.summary, titles)) if page.summary.strip() else ""
        text = f"{page.title} ({page.type})" + (f": {about}" if about else "")
        lines.append(_Line(SECTION_ENTITIES, text, score - 1.0, (page.id,)))

    head = ["# Core", "", GENERATED_NOTE, "", f"Name: {name}"]
    impression = []
    if profile and profile.summary.strip():
        impression = ["", " ".join(plain(profile.summary, titles).split())]
    budget = max_tokens - estimate_tokens("\n".join(head + impression)) - 20  # section headings
    if budget < 0 and impression:
        impression = ["", first_sentence(impression[1])]
        budget = max_tokens - estimate_tokens("\n".join(head + impression)) - 20

    chosen: list[_Line] = []
    for line in sorted(lines, key=lambda x: (-x.score, x.key)):
        cost = estimate_tokens(line.text) + 1
        if cost <= budget:
            chosen.append(line)
            budget -= cost

    out = head + impression
    for section in (SECTION_SITUATION, SECTION_ENTITIES):
        items = [x for x in chosen if x.section == section]
        if items:
            out += ["", f"## {section}", "", *(f"- {x.text}" for x in items)]
    return "\n".join(out) + "\n"


# --- writing -----------------------------------------------------------------------------------


def write_generated(
    vault: Vault, *, max_tokens: int = 1500, today: date | None = None
) -> list[Path]:
    """Rewrite ``index.md`` and ``core.md`` when their content changed; return changed paths."""
    targets = {
        vault.index_path: build_index(vault),
        vault.core_path: build_core(vault, max_tokens=max_tokens, today=today),
    }
    changed = []
    for path, text in targets.items():
        old = path.read_text(encoding="utf-8") if path.exists() else None
        if old != text:
            tmp = path.with_name(f".{path.name}.tmp")
            tmp.write_text(text, encoding="utf-8")
            tmp.replace(path)
            changed.append(path)
    return changed


def refresh_generated(
    vault: Vault, *, max_tokens: int = 1500, today: date | None = None, commit: bool = True
) -> list[Path]:
    """Regenerate and, if anything changed, commit the vault."""
    changed = write_generated(vault, max_tokens=max_tokens, today=today)
    if changed and commit:
        names = ", ".join(p.name for p in changed)
        gitops.commit_all(vault.root, f"brain: regenerate {names}")
    return changed
